-- Load distribution.DimAgent (dimension, SCD type 2).
-- One stored procedure per destination table (DE Policy v2, gold code standards).
-- The SELECT comes from models/gold/distribution/DimAgent.sql.
-- Generated by `python -m dbde render` from models/gold/distribution/DimAgent.yml. Do not edit: change the spec and render again.

CREATE OR REPLACE PROCEDURE ${gold_catalog}.distribution.LoadDimAgent(
    RunLoadDate DATE,
    RunLoadStepID STRING
)
LANGUAGE SQL
SQL SECURITY INVOKER
COMMENT 'Loads distribution.DimAgent with MERGE. Generated by dbde from models/gold/distribution/DimAgent.yml.'
AS BEGIN
    DECLARE RunTimestamp TIMESTAMP DEFAULT current_timestamp();
    DECLARE MaxKey BIGINT DEFAULT 0;

    -- New surrogate keys continue from the highest key in use
    -- (-1 is the unknown member).
    SET MaxKey = (
        SELECT coalesce(max(DimAgent_SK), 0)
        FROM ${gold_catalog}.distribution.DimAgent
        WHERE DimAgent_SK > 0
    );

    MERGE INTO ${gold_catalog}.distribution.DimAgent AS target
    USING (
        WITH source_rows AS (
            select
                agent.Agent_BK,
                agent.AgentName,
                agent.BranchCode,
                agent.IsActive
            from ${silver_catalog}.policy_admin.Agent as agent
        ),
        typed AS (
            SELECT
                CAST(source_rows.Agent_BK AS VARCHAR(20)) AS Agent_BK,
                CAST(source_rows.AgentName AS VARCHAR(200)) AS AgentName,
                CAST(source_rows.BranchCode AS VARCHAR(10)) AS BranchCode,
                CAST(source_rows.IsActive AS BOOLEAN) AS IsActive
            FROM source_rows
        ),
        -- Every source row is staged on its business key.
        -- Changed rows are staged again with a NULL key, so
        -- the MERGE both closes the current version and
        -- inserts the new one.
        changes AS (
            SELECT typed.Agent_BK AS MergeKey1, typed.*
            FROM typed
            UNION ALL
            SELECT CAST(NULL AS VARCHAR(20)) AS MergeKey1, typed.*
            FROM typed
            INNER JOIN ${gold_catalog}.distribution.DimAgent AS current_row
                ON current_row.Agent_BK = typed.Agent_BK
                AND current_row.IsCurrent
            WHERE NOT (current_row.AgentName <=> typed.AgentName)
                OR NOT (current_row.BranchCode <=> typed.BranchCode)
                OR NOT (current_row.IsActive <=> typed.IsActive)
        )
        SELECT
            changes.*,
            MaxKey + row_number() OVER (ORDER BY changes.Agent_BK, changes.MergeKey1 NULLS LAST)
                AS NewKey
        FROM changes
    ) AS source
    ON target.Agent_BK = source.MergeKey1
        AND target.IsCurrent
    WHEN MATCHED AND (
        NOT (target.AgentName <=> source.AgentName)
        OR NOT (target.BranchCode <=> source.BranchCode)
        OR NOT (target.IsActive <=> source.IsActive)
    ) THEN UPDATE SET
        EndDate = date_sub(RunLoadDate, 1),
        IsCurrent = false,
        LastUpdateLoadStepID = RunLoadStepID,
        LastUpdateTimestamp = RunTimestamp
    WHEN NOT MATCHED THEN INSERT (
        DimAgent_SK,
        Agent_BK,
        AgentName,
        BranchCode,
        IsActive,
        StartDate,
        EndDate,
        IsCurrent,
        InsertLoadStepID,
        InsertTimestamp,
        LastUpdateLoadStepID,
        LastUpdateTimestamp
    ) VALUES (
        source.NewKey,
        source.Agent_BK,
        source.AgentName,
        source.BranchCode,
        source.IsActive,
        CASE WHEN source.MergeKey1 IS NULL THEN RunLoadDate ELSE DATE'1900-01-01' END,
        DATE'9999-12-31',
        true,
        RunLoadStepID,
        RunTimestamp,
        RunLoadStepID,
        RunTimestamp
    );
END;
-- GO
